```

*   **`table class="table table-striped"`:**  This uses Bootstrap's base table styling and adds striped rows.
*   **`<thead>`:**  Contains the table headers.
*   **`<th>`:**  Each header cell.  Crucially, we add a `data-sort` attribute to each `<th>`.  This attribute tells our JavaScript what type of sorting to apply.  Possible values:
    *   `string`: For alphabetical sorting (names, text).
    *   `number`: For numerical sorting (ages, quantities).
    *   `date`: For date sorting.  (You'll need to format your dates consistently for this to work reliably).
*   **`<tbody>`:**  Contains the table data rows.
*   **`<tr>`:**  Each data row.
*   **`<td>`:**  Each data cell.

**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    sortTable(table, event.target.dataset.sort);
  }
});

function sortTable(table, sortType) {
  const tbody = table.querySelector('tbody');
  const rows = Array.from(tbody.querySelectorAll('tr'));

  rows.sort((a, b) => {
    const aValue = a.querySelector(`td:nth-child(${getColumnIndex(event.target)})`).textContent;
    const bValue = b.querySelector(`td:nth-child(${getColumnIndex(event.target)})`).textContent;

    switch (sortType) {
      case 'string':
        return aValue.localeCompare(bValue);
      case 'number':
        return Number(aValue) - Number(bValue);
      case 'date':
        return new Date(aValue) - new Date(bValue);
      default:
        return 0; // No sorting
    }
  });

  // Clear the table body and append the sorted rows
  tbody.innerHTML = '';
  rows.forEach(row => tbody.appendChild(row));
}

function getColumnIndex(header) {
    const headers = Array.from(table.querySelectorAll('th'));
    return headers.indexOf(header) + 1;
}
```

