class ClosedDoor : public Door
{
public:
    void open() override {
        // Implementation for opening a closed door
        throw std::logic_error("Cannot open a closed door directly.  Use a DoorOpener.");
    }

    Color color() const override {
        return Color{}; // Default color
    }

    void setColor(Color c) override {
        // Implementation for setting the color
    }
};

