)

func main() {
	// Configure AWS SDK
	cfg, err := config.LoadDefaultConfig(context.TODO(), config.WithRegion("us-east-2"))
	if err != nil {
		log.Fatalf("failed to load config, %v", err)
	}

	// Create Cognito Identity Provider client
	client := cognitoidentityprovider.NewClient(cfg)

	// Input parameters
	userPoolId := "us-east-2_4YtYz6hV0"
	groupName := "account:6412003a7a61c0beecdd16a7"

	// List users in group
	resp, err := client.ListUsersInGroup(context.TODO(), &cognitoidentityprovider.ListUsersInGroupInput{
		UserPoolId:     userPoolId,
		GroupName:      groupName,
	})
	if err != nil {
		log.Fatalf("failed to list users in group, %v", err)
	}

	// Iterate through users and filter based on custom attribute
	var attributeValues []string
	for _, user := range resp.Users {
		for _, attribute := range user.Attributes {
			if attribute.Name == "custom:profileType" && (attribute.Value == "1" || attribute.Value == "2") {
				// Extract all attribute values for this user
				for _, attr := range user.Attributes {
					attributeValues = append(attributeValues, attr.Value)
				}
